"""Exact restoration of bounded owned-work additions for earlier audits."""
import json
import re

ORIGINALS = json.loads(r'''{
  "pe_finish": "static QDF_STATUS mishare_pe_finish(struct scheduler_msg *msg, bool flushed)\n{\n\tstruct mishare_pe_request *req = msg->bodyptr;\n\tstruct wlan_objmgr_psoc *psoc;\n\tunsigned long cookie = 0;\n\tvoid *owner;\n\tuint8_t id;\n\tbool create;\n\tint ret;\n\n\tif (!req)\n\t\treturn QDF_STATUS_E_INVAL;\n\tpsoc = wlan_vdev_get_psoc(req->vdev);\n\tid = wlan_vdev_get_id(req->vdev);\n\towner = req->owner;\n\tcreate = req->create;\n\n/* MISHARE_SHUTDOWN_BEGIN:pe */\n\tif (!flushed && !mishare_runtime_work_allowed(req->vdev, req->owner))\n\t\tret = -ESHUTDOWN;\n\telse\n/* MISHARE_SHUTDOWN_END:pe */\n\tret = flushed ? -ECANCELED : mishare_pe_execute(req, &cookie);\n\twlan_objmgr_vdev_release_ref(req->vdev, WLAN_LEGACY_MAC_ID);\n\tqdf_mem_free(req);\n\tmsg->bodyptr = NULL;\n\t/* Last operation: owner may be drained after this notification. */\n\tmishare_runtime_ndi_pe_event(psoc, id, owner, create, cookie, ret);\n\treturn QDF_STATUS_SUCCESS;\n}\n",
  "pe_post": "int mishare_ndi_pe_post(struct wlan_objmgr_vdev *vdev, void *owner,\n\t\t\tbool create, unsigned long session_cookie)\n{\n\tstruct mishare_pe_request *req;\n\tstruct scheduler_msg msg = {0};\n\tQDF_STATUS status;\n\n\tif (!vdev || !owner || (create ? session_cookie != 0 : !session_cookie) ||\n\t    wlan_vdev_mlme_get_opmode(vdev) != QDF_PASSTHRU_MODE)\n\t\treturn -EINVAL;\n\treq = qdf_mem_malloc(sizeof(*req));\n\tif (!req)\n\t\treturn -ENOMEM;\n\tstatus = wlan_objmgr_vdev_try_get_ref(vdev, WLAN_LEGACY_MAC_ID);\n\tif (QDF_IS_STATUS_ERROR(status)) {\n\t\tqdf_mem_free(req);\n\t\treturn -ENODEV;\n\t}\n\treq->vdev = vdev;\n\treq->owner = owner;\n\treq->create = create;\n\treq->session_cookie = session_cookie;\n\tmsg.bodyptr = req;\n\tmsg.callback = mishare_pe_callback;\n\tmsg.flush_callback = mishare_pe_flush;\n\tstatus = scheduler_post_message(QDF_MODULE_ID_HDD, QDF_MODULE_ID_PE,\n\t\t\t\t\tQDF_MODULE_ID_TARGET_IF, &msg);\n\tif (QDF_IS_STATUS_ERROR(status)) {\n\t\t/* Native scheduler returns failure only before queue publication. */\n\t\twlan_objmgr_vdev_release_ref(vdev, WLAN_LEGACY_MAC_ID);\n\t\tqdf_mem_free(req);\n\t\treturn qdf_status_to_os_return(status);\n\t}\n\treturn 0;\n}\n",
  "channel_finish": "static QDF_STATUS mishare_channel_finish(struct scheduler_msg *msg, bool flushed)\n{\n\tstruct mishare_channel_request *req = msg->bodyptr;\n\tstruct wlan_objmgr_psoc *psoc;\n\tvoid *owner;\n\tuint32_t freq;\n\tuint8_t id;\n\tint ret;\n\n\tif (!req)\n\t\treturn QDF_STATUS_E_INVAL;\n\tpsoc = wlan_vdev_get_psoc(req->vdev);\n\tid = wlan_vdev_get_id(req->vdev);\n\towner = req->owner;\n\tfreq = req->freq;\n\n/* MISHARE_SHUTDOWN_BEGIN:channel */\n\tif (!flushed && !mishare_runtime_work_allowed(req->vdev, req->owner))\n\t\tret = -ESHUTDOWN;\n\telse\n/* MISHARE_SHUTDOWN_END:channel */\n\tret = flushed ? -ECANCELED : mishare_channel_execute(req);\n\twlan_objmgr_vdev_release_ref(req->vdev, WLAN_LEGACY_MAC_ID);\n\tqdf_mem_free(req);\n\tmsg->bodyptr = NULL;\n\tmishare_runtime_ndi_channel_event(psoc, id, owner, freq, ret);\n\treturn QDF_STATUS_SUCCESS;\n}\n",
  "channel_post": "int mishare_ndi_channel_post(struct wlan_objmgr_vdev *vdev, void *owner,\n\t\t\t      unsigned long cookie, uint32_t freq)\n{\n\tstruct mishare_channel_request *req;\n\tstruct scheduler_msg msg = {0};\n\tQDF_STATUS status;\n\n\tif (!vdev || !owner || !cookie || !freq ||\n\t    wlan_vdev_mlme_get_opmode(vdev) != QDF_PASSTHRU_MODE)\n\t\treturn -EINVAL;\n\treq = qdf_mem_malloc(sizeof(*req));\n\tif (!req)\n\t\treturn -ENOMEM;\n\tstatus = wlan_objmgr_vdev_try_get_ref(vdev, WLAN_LEGACY_MAC_ID);\n\tif (QDF_IS_STATUS_ERROR(status)) {\n\t\tqdf_mem_free(req);\n\t\treturn -ENODEV;\n\t}\n\treq->vdev = vdev;\n\treq->owner = owner;\n\treq->session_cookie = cookie;\n\treq->freq = freq;\n\tmsg.bodyptr = req;\n\tmsg.callback = mishare_channel_callback;\n\tmsg.flush_callback = mishare_channel_flush;\n\tstatus = scheduler_post_message(QDF_MODULE_ID_HDD, QDF_MODULE_ID_PE,\n\t\t\t\t\tQDF_MODULE_ID_TARGET_IF, &msg);\n\tif (QDF_IS_STATUS_ERROR(status)) {\n\t\twlan_objmgr_vdev_release_ref(vdev, WLAN_LEGACY_MAC_ID);\n\t\tqdf_mem_free(req);\n\t\treturn qdf_status_to_os_return(status);\n\t}\n\treturn 0;\n}\n",
  "start_plan_finish": "static QDF_STATUS mishare_start_plan_finish(struct scheduler_msg *msg, bool flushed)\n{\n\tstruct mishare_start_plan_request *req = msg->bodyptr;\n\tstruct mishare_ndi_start_summary summary = {0};\n\tstruct wlan_objmgr_psoc *psoc;\n\tvoid *owner;\n\tuint32_t freq;\n\tuint8_t id;\n\tint ret;\n\n\tif (!req)\n\t\treturn QDF_STATUS_E_INVAL;\n\tpsoc = wlan_vdev_get_psoc(req->channel.vdev);\n\tid = wlan_vdev_get_id(req->channel.vdev);\n\towner = req->channel.owner;\n\tfreq = req->channel.freq;\n\n/* MISHARE_SHUTDOWN_BEGIN:start_plan */\n\tif (!flushed && !mishare_runtime_work_allowed(req->channel.vdev, req->channel.owner))\n\t\tret = -ESHUTDOWN;\n\telse\n/* MISHARE_SHUTDOWN_END:start_plan */\n\tret = flushed ? -ECANCELED : mishare_start_plan_execute(req, &summary);\n\twlan_objmgr_vdev_release_ref(req->channel.vdev, WLAN_LEGACY_MAC_ID);\n\tqdf_mem_free(req);\n\tmsg->bodyptr = NULL;\n\tmishare_runtime_ndi_start_plan_event(psoc, id, owner, freq, ret,\n\t\t\t\t\t    ret ? NULL : &summary);\n\treturn QDF_STATUS_SUCCESS;\n}\n",
  "start_plan_post": "int mishare_ndi_start_plan_post(struct wlan_objmgr_vdev *vdev, void *owner,\n\t\t\t      unsigned long cookie, uint32_t freq)\n{\n\tstruct mishare_start_plan_request *req;\n\tstruct scheduler_msg msg = {0};\n\tQDF_STATUS status;\n\n\tif (!vdev || !owner || !cookie || !freq ||\n\t    wlan_vdev_mlme_get_opmode(vdev) != QDF_PASSTHRU_MODE)\n\t\treturn -EINVAL;\n\treq = qdf_mem_malloc(sizeof(*req));\n\tif (!req)\n\t\treturn -ENOMEM;\n\tstatus = wlan_objmgr_vdev_try_get_ref(vdev, WLAN_LEGACY_MAC_ID);\n\tif (QDF_IS_STATUS_ERROR(status)) {\n\t\tqdf_mem_free(req);\n\t\treturn -ENODEV;\n\t}\n\treq->channel.vdev = vdev;\n\treq->channel.owner = owner;\n\treq->channel.session_cookie = cookie;\n\treq->channel.freq = freq;\n\tmsg.bodyptr = req;\n\tmsg.callback = mishare_start_plan_callback;\n\tmsg.flush_callback = mishare_start_plan_flush;\n\tstatus = scheduler_post_message(QDF_MODULE_ID_HDD, QDF_MODULE_ID_PE,\n\t\t\t\t\tQDF_MODULE_ID_TARGET_IF, &msg);\n\tif (QDF_IS_STATUS_ERROR(status)) {\n\t\twlan_objmgr_vdev_release_ref(vdev, WLAN_LEGACY_MAC_ID);\n\t\tqdf_mem_free(req);\n\t\treturn qdf_status_to_os_return(status);\n\t}\n\treturn 0;\n}\n",
  "cds_include": "",
  "cds_mc_stopped": ""
}''')

def remove_work_additions(text):
    from mishare_recovery_origins import remove_recovery_additions
    text = remove_recovery_additions(text)
    for tag, original in ORIGINALS.items():
        pattern = (r'\n/\* MISHARE_WORK_BEGIN:' + tag +
                   r' \*/\n.*?/\* MISHARE_WORK_END:' + tag + r' \*/\n')
        text, count = re.subn(pattern, lambda m: original, text, flags=re.S)
        if count > 1:
            raise ValueError('Duplicate owned work insertion: ' + tag)
    if 'MISHARE_WORK_' in text:
        raise ValueError('Unknown owned work insertion')
    return text
